import{_ as a,o as l,c as t,a3 as i}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Empfohlene lokale Modelle","description":"Nach VRAM lokale LLMs (Pfadtest, Roleplay, Chinesisch) für Ollama, LM Studio, KoboldCPP, llama.cpp und MiniTavern.","frontmatter":{"title":"Empfohlene lokale Modelle","description":"Nach VRAM lokale LLMs (Pfadtest, Roleplay, Chinesisch) für Ollama, LM Studio, KoboldCPP, llama.cpp und MiniTavern.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Empfohlene lokale Modelle · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Nach VRAM lokale LLMs (Pfadtest, Roleplay, Chinesisch) für Ollama, LM Studio, KoboldCPP, llama.cpp und MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/local/models"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/local/models"}]]},"headers":[],"relativePath":"de/local/models.md","filePath":"de/local/models.md","lastUpdated":1787224147000}'),n={name:"de/local/models.md"};function o(r,e,s,d,h,p){return l(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="empfohlene-modelle" tabindex="-1">Empfohlene Modelle <a class="header-anchor" href="#empfohlene-modelle" aria-label="Permalink to &quot;Empfohlene Modelle&quot;">​</a></h1><p>Namen und Downloads je Tool; Tabelle = <strong>Größe und Zweck</strong>. Pull-/Dateinamen laut Tool-Seiten.</p><h2 id="große-nach-hardware" tabindex="-1">Größe nach Hardware <a class="header-anchor" href="#große-nach-hardware" aria-label="Permalink to &quot;Größe nach Hardware&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ca. Größe</th><th>RAM/VRAM grob</th><th>Geeignet für</th></tr></thead><tbody><tr><td>1B–3B</td><td>ca. 4–8GB</td><td><strong>Pfad zuerst prüfen</strong>, schwache Hardware</td></tr><tr><td>7B–9B</td><td>ca. 8–16GB</td><td>Roleplay-Sweetspot</td></tr><tr><td>12B–14B</td><td>16GB+</td><td>bessere Qualität, Tempo je GPU</td></tr><tr><td>32B+</td><td>24GB+ oder starke Quantisierung</td><td>High-End; Handy wartet länger</td></tr></tbody></table><p>Kleinere Quantisierung (Q4 / Q5 / IQ …) spart Ressourcen, Qualität leicht runter. GGUF: Community-übliche <code>Q4_K_M</code> / <code>Q5_K_M</code>.</p><h2 id="pfadtest-kleine-modelle-zuerst" tabindex="-1">Pfadtest (kleine Modelle zuerst) <a class="header-anchor" href="#pfadtest-kleine-modelle-zuerst" aria-label="Permalink to &quot;Pfadtest (kleine Modelle zuerst)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Szenario</th><th>Ollama-Beispiel</th><th>GGUF / sonst</th></tr></thead><tbody><tr><td>schnellster Test</td><td><code>llama3.2:3b</code>, <code>qwen2.5:3b</code></td><td>beliebiges 3B Instruct-GGUF</td></tr><tr><td>Chinesisch leicht</td><td><code>qwen2.5:3b</code> / <code>qwen2.5:7b</code></td><td>Qwen2.5 Instruct quantisiert</td></tr></tbody></table><p>Zuerst <a href="/ultra_guides/de/connect-app/minitavern">Verbindungstest</a>, dann größere Modelle.</p><h2 id="roleplay-hinweise" tabindex="-1">Roleplay-Hinweise <a class="header-anchor" href="#roleplay-hinweise" aria-label="Permalink to &quot;Roleplay-Hinweise&quot;">​</a></h2><ul><li><strong>Instruct / Chat</strong>-Finetunes, keine reinen Base-Completion-Modelle.</li><li>Community-RP-Weights ändern sich; was stabil lädt und genug Kontext hat, zählt.</li><li>Zu kleiner Kontext schneidet Lorebook/Settings; bei 7B zuerst 4k–8k, dann nach VRAM erhöhen.</li><li>In MiniTavern <strong>Modellname exakt</strong> wie in der Tool-Liste (inkl. Tag <code>:7b</code>).</li></ul><h2 id="ollama-pull-beispiele" tabindex="-1">Ollama-Pull-Beispiele <a class="header-anchor" href="#ollama-pull-beispiele" aria-label="Permalink to &quot;Ollama-Pull-Beispiele&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:14b</span></span></code></pre></div><p>Mehr: <a href="/ultra_guides/de/ollama/models">Ollama · Modelle</a>.</p><h2 id="lm-studio-koboldcpp-llama-cpp" tabindex="-1">LM Studio / KoboldCPP / llama.cpp <a class="header-anchor" href="#lm-studio-koboldcpp-llama-cpp" aria-label="Permalink to &quot;LM Studio / KoboldCPP / llama.cpp&quot;">​</a></h2><ol><li><strong>GGUF</strong> von <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> usw. (Lizenz &amp; Quelle prüfen).</li><li>In dem Tool laden.</li><li>API / Server an → <strong>model id</strong> aus der UI in MiniTavern.</li></ol><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><p><a href="/ultra_guides/de/local/tools">Tool-Übersicht</a> → «Dienst starten» des Tools → <a href="/ultra_guides/de/connect-app/minitavern">In MiniTavern konfigurieren</a></p>`,17)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
